import crypto from "node:crypto"
import { type NextRequest, NextResponse } from "next/server"
import { sanitizeAuthRedirectPath } from "@/lib/auth-redirect"

function generateSecureRandomString(length: number) {
  return crypto
    .randomBytes(Math.ceil(length / 2))
    .toString("hex")
    .substring(0, length)
}

export async function GET(req: NextRequest) {
  const state = generateSecureRandomString(43)
  const nonce = generateSecureRandomString(43)
  const code_verifier = generateSecureRandomString(43)
  const code_challenge = crypto.createHash("sha256").update(code_verifier).digest("base64url")
  const returnTo = sanitizeAuthRedirectPath(req.nextUrl.searchParams.get("next"))
  const prompt = req.nextUrl.searchParams.get("prompt")
  const secure = process.env.NODE_ENV === "production"

  const queryParams = new URLSearchParams({
    client_id: process.env.NEXT_PUBLIC_CLIENT_ID as string,
    redirect_uri: `${req.nextUrl.origin}/api/auth/callback`,
    state,
    nonce,
    code_challenge,
    code_challenge_method: "S256",
    response_type: "code",
    // Include project env var scopes so workflow sandbox setup can read NPM_TOKEN and other
    // private package auth variables directly from the selected project configuration.
    scope:
      "openid email profile offline_access user team project project.write deployment deployment.write project-env-vars global-project-env-vars"
  })

  if (prompt === "consent") {
    queryParams.set("prompt", "consent")
  }

  const authorizationUrl = `https://vercel.com/oauth/authorize?${queryParams.toString()}`
  const response = NextResponse.redirect(authorizationUrl)

  response.cookies.set("oauth_state", state, {
    maxAge: 10 * 60,
    path: "/",
    secure,
    httpOnly: true,
    sameSite: "lax"
  })
  response.cookies.set("oauth_nonce", nonce, {
    maxAge: 10 * 60,
    path: "/",
    secure,
    httpOnly: true,
    sameSite: "lax"
  })
  response.cookies.set("oauth_code_verifier", code_verifier, {
    maxAge: 10 * 60,
    path: "/",
    secure,
    httpOnly: true,
    sameSite: "lax"
  })
  response.cookies.set("oauth_return_to", returnTo, {
    maxAge: 10 * 60,
    path: "/",
    secure,
    httpOnly: true,
    sameSite: "lax"
  })

  return response
}

import { cookies } from "next/headers"
import { NextResponse } from "next/server"
import { getSignInPath } from "@/lib/auth-redirect"

const AUTH_COOKIE_NAMES = [
  "access_token",
  "refresh_token",
  "oauth_state",
  "oauth_nonce",
  "oauth_code_verifier",
  "oauth_return_to"
]

async function revokeAuthToken(): Promise<number> {
  const cookieStore = await cookies()
  const accessToken = [REDACTED]"access_token")?.value
  let status = 200

  if (accessToken) {
    const credentials = `${process.env.NEXT_PUBLIC_CLIENT_ID}:${process.env.CLIENT_SECRET}`

    try {
      const response = await fetch("https://api.vercel.com/login/oauth/token/revoke", {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          Authorization: `Basic ${Buffer.from(credentials).toString("base64")}`
        },
        body: new URLSearchParams({
          token: accessToken
        })
      })

      status = response.status

      if (!response.ok) {
        const errorData = await response.json().catch(() => null)
        console.error("Error revoking token:", errorData)
      }
    } catch (error) {
      console.error("Error revoking token:", error)
      status = 200
    }
  }

  return status
}

function clearAuthCookies(response: NextResponse) {
  for (const cookieName of AUTH_COOKIE_NAMES) {
    response.cookies.set(cookieName, "", {
      path: "/",
      maxAge: 0
    })
  }
}

export async function POST() {
  const status = await revokeAuthToken()
  const response = NextResponse.json({}, { status })
  clearAuthCookies(response)

  return response
}

export async function GET(request: Request) {
  await revokeAuthToken()
  const response = NextResponse.redirect(new URL(getSignInPath(undefined, { prompt: "consent" }), request.url))
  clearAuthCookies(response)

  return response
}

import { connection, type NextRequest, NextResponse } from "next/server"
import { sanitizeAuthRedirectPath } from "@/lib/auth-redirect"

interface TokenData {
  access_token: string
  token_type: string
  id_token: string
  expires_in: number
  scope: string
  refresh_token: string
}

export async function GET(request: NextRequest) {
  await connection()

  try {
    const url = new URL(request.url)
    const code = url.searchParams.get("code")
    const state = url.searchParams.get("state")
    const error = url.searchParams.get("error")
    const errorDescription = url.searchParams.get("error_description")

    // Handle OAuth errors from the provider
    if (error) {
      const errorUrl = new URL("/auth/error", request.url)
      errorUrl.searchParams.set("error", error)
      if (errorDescription) {
        errorUrl.searchParams.set("error_description", errorDescription)
      }
      return Response.redirect(errorUrl)
    }

    if (!code) {
      throw new Error("Authorization code is required")
    }

    const storedState = request.cookies.get("oauth_state")?.value
    const storedNonce = request.cookies.get("oauth_nonce")?.value
    const codeVerifier = request.cookies.get("oauth_code_verifier")?.value
    const returnTo = sanitizeAuthRedirectPath(request.cookies.get("oauth_return_to")?.value)

    if (!validate(state, storedState)) {
      throw new Error("State mismatch")
    }

    const tokenData = await exchangeCodeForToken(code, codeVerifier, request.nextUrl.origin)
    const decodedNonce = decodeNonce(tokenData.id_token)

    if (!validate(decodedNonce, storedNonce)) {
      throw new Error("Nonce mismatch")
    }

    const response = NextResponse.redirect(new URL(returnTo, request.url))
    setAuthCookies(response, tokenData)
    clearOAuthCookies(response)

    return response
  } catch (error) {
    console.error("OAuth callback error:", error)
    return NextResponse.redirect(new URL("/auth/error", request.url))
  }
}

function validate(value: string | null, storedValue: string | undefined): boolean {
  if (!value || !storedValue) {
    return false
  }
  return value === storedValue
}

function decodeNonce(idToken: string): string {
  const payload = idToken.split(".")[1]
  const decodedPayload = Buffer.from(payload, "base64").toString("utf-8")
  const nonceMatch = decodedPayload.match(/"nonce":"([^"]+)"/)
  return nonceMatch ? nonceMatch[1] : ""
}

async function exchangeCodeForToken(
  code: string,
  code_verifier: string | undefined,
  requestOrigin: string
): Promise<TokenData> {
  const params = new URLSearchParams({
    grant_type: "authorization_code",
    client_id: process.env.NEXT_PUBLIC_CLIENT_ID as string,
    client_secret: [REDACTED] as string,
    code: code,
    code_verifier: code_verifier || "",
    redirect_uri: `${requestOrigin}/api/auth/callback`
  })

  const response = await fetch("https://api.vercel.com/login/oauth/token", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded"
    },
    body: params.toString()
  })

  if (!response.ok) {
    const errorData = await response.json()
    throw new Error(`Failed to exchange code for token: [REDACTED]}`)
  }

  const tokenData = await response.json()
  console.log("Token exchange response - scope:", tokenData.scope)
  return tokenData
}

function setAuthCookies(response: NextResponse, tokenData: TokenData) {
  const secure = process.env.NODE_ENV === "production"

  response.cookies.set("access_token", tokenData.access_token, {
    httpOnly: true,
    secure,
    sameSite: "lax",
    path: "/",
    maxAge: tokenData.expires_in
  })

  response.cookies.set("refresh_token", tokenData.refresh_token, {
    httpOnly: true,
    secure,
    sameSite: "lax",
    path: "/",
    maxAge: 60 * 60 * 24 * 30 // 30 days
  })
}

function clearOAuthCookies(response: NextResponse) {
  for (const cookieName of ["oauth_state", "oauth_nonce", "oauth_code_verifier", "oauth_return_to"]) {
    response.cookies.set(cookieName, "", {
      path: "/",
      maxAge: 0
    })
  }
}

