import { describe, expect, it } from "vitest"

import { redactSensitiveReportText } from "./report-redaction"

describe("redactSensitiveReportText", () => {
  it("redacts Vercel and model provider token assignments", () => {
    const redacted = redactSensitiveReportText(
      "VERCEL_TOKEN=[REDACTED]'openai-secret'"
    )

    expect(redacted).toContain("VERCEL_TOKEN=[redacted]")
    expect(redacted).toContain("AI_GATEWAY_API_KEY=[redacted]")
    expect(redacted).toContain("OPENAI_API_KEY=[redacted]")
    expect(redacted).not.toContain("secret-123")
    expect(redacted).not.toContain("gw_secret")
    expect(redacted).not.toContain("openai-secret")
  })
})

import { describe, expect, it } from "vitest"
import { getAgentByName, KNOWN_AGENTS } from "./agent-selection.js"

describe("agent-selection", () => {
  it("should include blackbox in known agents", () => {
    const blackbox = getAgentByName("blackbox")
    expect(blackbox?.binary).toBe("blackbox")
  })

  it("should use plain quoted d3k prompt for codex variants", () => {
    const codex = getAgentByName("codex")
    const codexYolo = getAgentByName("codex-yolo")

    expect(codex?.command).toContain('"load the d3k skill and await further instruction"')
    expect(codexYolo?.command).toContain('"load the d3k skill and await further instruction"')
  })

  it("should append the d3k prompt to blackbox", () => {
    const blackbox = getAgentByName("blackbox")

    expect(blackbox?.command).toContain('"load the d3k skill and await further instruction"')
  })

  it("should not include legacy escaped single-quote prompt sequences", () => {
    const commands = KNOWN_AGENTS.map((agent) => agent.command).filter((command): command is string => Boolean(command))
    const hasLegacyEscaping = commands.some((command) => command.includes("'\\''"))

    expect(hasLegacyEscaping).toBe(false)
  })
})

