async function collectTextFiles(baseDir: string, relativeDir = ""): Promise<Array<{ path: string; content: string }>> {
  const dir = path.join(baseDir, relativeDir)
  const entries = await readdir(dir, { withFileTypes: true })
  const files: Array<{ path: string; content: string }> = []

  for (const entry of entries) {
    const nextRelative = relativeDir ? path.join(relativeDir, entry.name) : entry.name
    if (entry.isDirectory()) {
      files.push(...(await collectTextFiles(baseDir, nextRelative)))
      continue
    }
    const absolutePath = path.join(baseDir, nextRelative)
    files.push({
      path: nextRelative.replaceAll("\\", "/"),
      content: await readFile(absolutePath, "utf8")
    })
  }

  return files
}

async function resolvePackagedSkillFiles(
  input: DevAgentEveInput
): Promise<{ packagedSkills: string[]; files: Array<{ path: string; content: string }> }> {
  const packagedSkills: string[] = []
  const files: Array<{ path: string; content: string }> = []
  const cwd = process.cwd()
  const pluginCacheRoot = path.join(
    process.env.HOME || "",
    ".codex/plugins/cache/openai-curated/vercel/f78e3ad49297672a905eb7afb6aa0cef34edc79e/skills"
  )

  for (const skill of input.skillRefs) {
    const candidateDirs = [
      path.join(cwd, ".agents/skills", skill.skillName),
      path.join(cwd, "..", ".agents/skills", skill.skillName),
      path.join(pluginCacheRoot, skill.skillName)
    ]

    let resolvedDir: string | null = null
    for (const candidate of candidateDirs) {
      try {
        const entries = await readdir(/* turbopackIgnore: true */ candidate)
        if (entries.length > 0) {
          resolvedDir = candidate
          break
        }
      } catch {
        // Try next candidate.
      }
    }

    if (!resolvedDir) continue

    const skillFiles = await collectTextFiles(resolvedDir)
    if (skillFiles.length === 0) continue

    packagedSkills.push(skill.displayName || skill.skillName)
    files.push(
      ...skillFiles.map((file) => ({
        path: `agent/skills/${skill.skillName}/${file.path}`,
        content: file.content
      }))
    )
  }

  return { packagedSkills, files }
}

export async function createDevAgentEveSource(input: DevAgentEveInput, revision: number): Promise<DevAgentEveSource> {
  const canonicalSpec = createCanonicalSpec(input)
  const specHash = createHash("sha256").update(JSON.stringify(canonicalSpec)).digest("hex")
  const slug = slugify(input.name) || input.id
  const packageName = `dev-agent-${slug}`
  const packageVersion = `0.0.${revision}`
  const systemPrompt = renderSystemPrompt(input)
  const sourceLabel = `${input.name.trim()} v${revision}`
  const packagedSkillData = await resolvePackagedSkillFiles(input)
  const packagedSkills = [...packagedSkillData.packagedSkills, "dev3000-agent-runbook"]
  const disabledFrameworkTools = isDeepSecEveInput(input)
    ? [
        {
          path: "agent/tools/read_file.ts",
          content: renderDisabledFrameworkTool()
        },
        {
          path: "agent/tools/write_file.ts",
          content: renderDisabledFrameworkTool()
        }
      ]
    : []
  const disabledAutomationTools = getDisabledAutomationToolFiles()
  const files = [
    {
      path: "package.json",
      content: JSON.stringify(
        {
          name: packageName,
          version: packageVersion,
          private: true,
          type: "module",
          scripts: {
            build: "eve build",
            dev: "eve dev",
            "patch-workflow-world": "node scripts/patch-workflow-world-local.mjs",
            typecheck: "tsgo"
          },
          dependencies: {
            ai: EVE_AI_PACKAGE_VERSION,
            [EVE_PACKAGE_NAME]: EVE_PACKAGE_VERSION,
            zod: "^4.4.3"
          },
          devDependencies: {
            "@types/node": "^24.12.2",
            "@typescript/native-preview": "7.0.0-dev.20260707.2"
          }
        },
        null,
        2
      )
    },
    {
      path: "tsconfig.json",
      content: JSON.stringify(
        {
          compilerOptions: {
            target: "ES2022",
            module: "NodeNext",
            moduleResolution: "NodeNext",
            strict: true,
            noEmit: true,
            esModuleInterop: true,
            skipLibCheck: true,
            types: ["node"]
          },
          include: ["agent/**/*.ts"]
        },
        null,
        2
      )
    },
    {
      path: "README.md",
      content: renderReadme(input, revision, specHash)
    },
    {
      path: "agent/agent.ts",
      content: renderGeneratedAgentDefinition(input)
    },
    {
      path: "agent/instructions.md",
      content: systemPrompt
    },
    {
      path: "agent/instructions/runtime-contract.md",
      content: renderRuntimeContractLayer(input)
    },
    {
      path: "agent/instructions/evaluation.md",
      content: renderEvaluationLayer(input)
    },
    {
      path: "agent/instructions/skills.md",
      content: renderSkillsLayer(input)
    },
    {
      path: "agent/channels/eve.ts",
      content: renderEveRuntimeMessageChannel()
    },
    {
      path: "agent/channels/dev3000.ts",
      content: renderEveRuntimeTaskChannel()
    },
    {
      path: "agent/sandbox/sandbox.ts",
      content: renderGeneratedSandboxDefinition()
    },
    {
      path: "agent/sandbox/workspace/README.md",
      content: renderGeneratedWorkspaceReadme()
    },
    {
      path: "scripts/patch-workflow-world-local.mjs",
      content: renderWorkflowWorldLocalPatchScript()
    },
    {
      path: "agent/spec.json",
      content: JSON.stringify(canonicalSpec, null, 2)
    },
    {
      path: "agent/skills-manifest.json",
      content: JSON.stringify(
        {
          packagedSkills
        },
        null,
        2
      )
    },
    {
      path: "agent/skills/dev3000-agent-runbook/SKILL.md",
      content: renderExecutionRunbookSkill(input)
    },
    ...disabledAutomationTools,
    ...disabledFrameworkTools,
    ...packagedSkillData.files
  ]

  return {
    packageName,
    packageVersion,
    systemPrompt,
    sourceLabel,
    specHash,
    packagedSkills,
    compiledSpec: canonicalSpec,
    files
  }
}

export function createDevAgentEveArtifactDescriptor(
  input: DevAgentEveInput,
  revision = 1,
  generatedAt = new Date().toISOString()
): DevAgentEveArtifact {
  const canonicalSpec = createCanonicalSpec(input)
  const specHash = createHash("sha256").update(JSON.stringify(canonicalSpec)).digest("hex")
  const slug = slugify(input.name) || input.id
  const packageName = `dev-agent-${slug}`
  const packageVersion = `0.0.${revision}`
  const sourceLabel = `${input.name.trim()} v${revision}`
  const systemPrompt = renderSystemPrompt(input)
  return {
    framework: "eve",
    revision,
    specHash,
    generatedAt,
    packageName,
    packageVersion,
    sourceLabel,
    systemPrompt,
    compiledSpec: canonicalSpec
  }
}

import { describe, expect, it } from "vitest"
import { extractAutomationProtectionBypassToken } from "./vercel-protection-bypass"

describe("extractAutomationProtectionBypassToken", () => {
  it("supports the legacy secret field", () => {
    expect(extractAutomationProtectionBypassToken({ secret: "[REDACTED]" })).toBe("legacy-secret")
  })

  it("supports a direct protectionBypass string", () => {
    expect(extractAutomationProtectionBypassToken({ protectionBypass: "direct-secret" })).toBe("direct-secret")
  })

  it("extracts the automation bypass token from Vercel's protectionBypass map", () => {
    expect(
      extractAutomationProtectionBypassToken({
        protectionBypass: {
          "sso-secret": { scope: "sso" },
          "automation-secret": { scope: "automation-bypass" }
        }
      })
    ).toBe("automation-secret")
  })

  it("prefers the newest automation bypass token when project settings contain several", () => {
    expect(
      extractAutomationProtectionBypassToken({
        protectionBypass: {
          "old-automation-secret": { scope: "automation-bypass", createdAt: 100 },
          "sso-secret": { scope: "sso", createdAt: 300 },
          "new-automation-secret": { scope: "automation-bypass", createdAt: 200 }
        }
      })
    ).toBe("new-automation-secret")
  })
})

import { describe, expect, it } from "vitest"

import {
  buildVercelCliSandboxEnv,
  buildVercelProjectJsonContent,
  normalizeVercelCliSandboxContext
} from "./vercel-cli-sandbox-context"

describe("vercel CLI sandbox context", () => {
  it("normalizes blank values", () => {
    expect(
      normalizeVercelCliSandboxContext({
        projectId: " prj_123 ",
        teamId: " ",
        token: ""
      })
    ).toEqual({
      projectId: "prj_123",
      teamId: undefined,
      token: undefined
    })
  })

  it("builds the process env used by the Vercel CLI", () => {
    expect(
      buildVercelCliSandboxEnv({
        projectId: "prj_123",
        teamId: "team_123",
        token: "[REDACTED]"
      })
    ).toEqual({
      VERCEL_ORG_ID: "team_123",
      VERCEL_PROJECT_ID: "prj_123",
      VERCEL_TEAM_ID: "team_123",
      VERCEL_TOKEN: "[REDACTED]"
    })
  })

  it("writes linked project metadata without token material", () => {
    const content = buildVercelProjectJsonContent({
      projectId: "prj_123",
      teamId: "team_123",
      token: "[REDACTED]"
    })

    expect(content).toBe('{\n  "projectId": "prj_123",\n  "orgId": "team_123"\n}\n')
    expect(content).not.toContain("secret-token")
  })

  it("does not write project metadata without a target project id", () => {
    expect(buildVercelProjectJsonContent({ teamId: "team_123", token: "[REDACTED]" })).toBeNull()
  })
})

name: Release

on:
  push:
    branches:
      - main
  workflow_dispatch:

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: false

permissions:
  contents: write
  id-token: write

jobs:
  check-release:
    name: Check for release candidate
    if: github.ref == 'refs/heads/main'
    runs-on: ubuntu-latest
    outputs:
      should_release: ${{ steps.check.outputs.should_release }}
      version: ${{ steps.check.outputs.version }}
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          ref: main

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: "24"
          registry-url: "https://registry.npmjs.org"

      - name: Compare version to npm
        id: check
        run: |
          LOCAL_VERSION=$(node -p "require('./package.json').version")
          echo "Local version: $LOCAL_VERSION"
          echo "version=$LOCAL_VERSION" >> "$GITHUB_OUTPUT"

          if [[ "$LOCAL_VERSION" == *"-canary" ]]; then
            echo "Canary version detected, skipping release"
            echo "should_release=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi

          NPM_VERSION=$(npm view dev3000 version 2>/dev/null || echo "0.0.0")
          echo "Registry version: $NPM_VERSION"

          if [ "$LOCAL_VERSION" != "$NPM_VERSION" ]; then
            echo "Version changed: $NPM_VERSION -> $LOCAL_VERSION"
            echo "should_release=true" >> "$GITHUB_OUTPUT"
          else
            echo "Version unchanged, skipping release"
            echo "should_release=false" >> "$GITHUB_OUTPUT"
          fi

  publish:
    name: Publish release
    needs: check-release
    if: needs.check-release.outputs.should_release == 'true'
    runs-on: macos-latest
    env:
      RELEASE_VERSION: ${{ needs.check-release.outputs.version }}
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          token: ${{ secrets.GITHUB_TOKEN }}

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: "24"
          registry-url: "https://registry.npmjs.org"

      - name: Setup Bun
        uses: oven-sh/setup-bun@v2
        with:
          bun-version: latest

      - name: Install dependencies
        run: bun install --frozen-lockfile

      - name: Run release checks
        run: ./scripts/test-release.sh

      - name: Build skill-runner shell manifest
        env:
          SKILL_RUNNER_SHELL_VERSION: ${{ env.RELEASE_VERSION }}
          SKILL_RUNNER_SHELL_COMMIT: ${{ github.sha }}
          SKILL_RUNNER_SHELL_SOURCE_BASE_URL: https://raw.githubusercontent.com/vercel-labs/dev3000/${{ github.sha }}
        run: bun run build:skill-runner-shell

      - name: Build release binaries
        run: ./scripts/prepare-platform-packages.sh

      - name: Publish @d3k/darwin-arm64 to npm
        run: npm publish --provenance --access public
        working-directory: packages/d3k-darwin-arm64

      - name: Publish @d3k/linux-x64 to npm
        run: npm publish --provenance --access public
        working-directory: packages/d3k-linux-x64

      - name: Publish @d3k/windows-x64 to npm
        run: npm publish --provenance --access public
        working-directory: packages/d3k-windows-x64

      - name: Publish dev3000 to npm
        run: npm publish --provenance --access public

      - name: Extract changelog entry
        run: |
          awk -v version="$RELEASE_VERSION" '
            $0 ~ "^## \\[" version "\\]" {found=1; next}
            found && /^## \[/ {exit}
            found {print}
          ' CHANGELOG.md > /tmp/release-notes.md

          LINES=$(wc -l < /tmp/release-notes.md | tr -d ' ')
          if [ "$LINES" -lt 2 ]; then
            echo "Error: no release notes found for $RELEASE_VERSION in CHANGELOG.md"
            exit 1
          fi

      - name: Create GitHub release
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          TAG="v$RELEASE_VERSION"
          if gh release view "$TAG" >/dev/null 2>&1; then
            echo "GitHub release $TAG already exists, skipping"
          else
            gh release create "$TAG" \
              --title "$TAG" \
              --notes-file /tmp/release-notes.md
          fi

      - name: Upload skill-runner shell manifest
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          gh release upload "v$RELEASE_VERSION" \
            ".artifacts/skill-runner-shell/skill-runner-shell-$RELEASE_VERSION.json" \
            --clobber

      - name: Calculate next canary version
        run: |
          NEXT_CANARY_VERSION=$(node -e "
            const version = process.env.RELEASE_VERSION;
            const semver = version.split('.');
            semver[2] = String(Number.parseInt(semver[2], 10) + 1);
            console.log(semver.join('.') + '-canary');
          ")

          echo "Next canary version: $NEXT_CANARY_VERSION"
          echo "NEXT_CANARY_VERSION=$NEXT_CANARY_VERSION" >> "$GITHUB_ENV"

      - name: Bump main back to next canary
        run: |
          npm version "$NEXT_CANARY_VERSION" --no-git-tag-version

          node -e "
            const fs = require('fs');
            const nextVersion = process.env.NEXT_CANARY_VERSION;
            const packagePaths = [
              'packages/d3k-darwin-arm64/package.json',
              'packages/d3k-linux-x64/package.json',
              'packages/d3k-windows-x64/package.json'
            ];

            for (const pkgPath of packagePaths) {
              const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
              pkg.version = nextVersion;
              fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\\n');
            }

            const rootPkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
            rootPkg.optionalDependencies = rootPkg.optionalDependencies || {};
            rootPkg.optionalDependencies['@d3k/darwin-arm64'] = nextVersion;
            rootPkg.optionalDependencies['@d3k/linux-x64'] = nextVersion;
            rootPkg.optionalDependencies['@d3k/windows-x64'] = nextVersion;
            fs.writeFileSync('package.json', JSON.stringify(rootPkg, null, 2) + '\\n');
          "

          node <<'NODE'
            const fs = require("fs");
            const nextVersion = process.env.NEXT_CANARY_VERSION;
            const platformPackages = [
              "@d3k/darwin-arm64",
              "@d3k/linux-x64",
              "@d3k/windows-x64"
            ];
            const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
            let lockfile = fs.readFileSync("bun.lock", "utf8");

            for (const packageName of platformPackages) {
              const escapedPackageName = escapeRegExp(packageName);
              lockfile = lockfile.replace(
                new RegExp(`("${escapedPackageName}":\\s*")[^"]+(")`, "g"),
                `$1${nextVersion}$2`
              );
              lockfile = lockfile.replace(
                new RegExp(`('${escapedPackageName}':\\n\\s+specifier: )[^\\n]+(\\n\\s+version: )[^\\n]+`),
                `$1${nextVersion}$2${nextVersion}`
              );
              lockfile = lockfile.replace(
                new RegExp(`'${escapedPackageName}@[^']+'`, "g"),
                `'${packageName}@${nextVersion}'`
              );
            }

            fs.writeFileSync("bun.lock", lockfile);
          NODE

      - name: Commit and push next canary
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          export EXPECTED_HEAD_OID="$(git rev-parse HEAD)"

          node <<'NODE'
            const fs = require("fs");
            const paths = [
              "package.json",
              "packages/d3k-darwin-arm64/package.json",
              "packages/d3k-linux-x64/package.json",
              "packages/d3k-windows-x64/package.json",
              "bun.lock"
            ];
            const additions = paths.map((path) => ({
              path,
              contents: fs.readFileSync(path).toString("base64")
            }));

            const payload = {
              query: `
                mutation($input: CreateCommitOnBranchInput!) {
                  createCommitOnBranch(input: $input) {
                    commit { oid url }
                  }
                }
              `,
              variables: {
                input: {
                  branch: {
                    repositoryNameWithOwner: process.env.GITHUB_REPOSITORY,
                    branchName: "main"
                  },
                  message: {
                    headline: `Bump to v${process.env.NEXT_CANARY_VERSION} for local development`
                  },
                  expectedHeadOid: process.env.EXPECTED_HEAD_OID,
                  fileChanges: { additions }
                }
              }
            };

            fs.writeFileSync("/tmp/create-canary-commit.json", JSON.stringify(payload));
          NODE

          # GitHub signs commits created by this mutation, satisfying the
          # verified-signature rule on main without storing a signing key.
          gh api graphql --input /tmp/create-canary-commit.json

{
